import{_ as p,a0 as i,w as n,s as d,ao as h,I as r,x as t,a1 as o,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"智能机应该舍弃耳机插口吗？以下是我们的观点 | LCTT x X-CMD","titleTemplate":false,"description":"智能机应该舍弃耳机插口吗？以下是我们的观点 | LCTT (201612) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"智能机应该舍弃耳机插口吗？以下是我们的观点 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"智能机应该舍弃耳机插口吗？以下是我们的观点 | LCTT (201612) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201612/20160915 Should Smartphones Do Away with the Headphone Jack Here Are Our Though","title":"智能机应该舍弃耳机插口吗？以下是我们的观点","tag":"201612","desc":""},"relativePath":"201612/20160915 Should Smartphones Do Away with the Headphone Jack Here Are Our Though.md","filePath":"[post].md"}'),m={name:"201612/20160915 Should Smartphones Do Away with the Headphone Jack Here Are Our Though.md"};function u(l,e,f,k,T,g){const a=i("Link");return n(),d("div",null,[e[15]||(e[15]=h('<h1 id="智能机应该舍弃耳机插口吗-以下是我们的观点" tabindex="-1">智能机应该舍弃耳机插口吗？以下是我们的观点 <a class="header-anchor" href="#智能机应该舍弃耳机插口吗-以下是我们的观点" aria-label="Permalink to “智能机应该舍弃耳机插口吗？以下是我们的观点”">​</a></h1><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/09/Writers-Opinion-Headphone-Featured.jpg" alt=""></p><p>尽管苹果公司将在 iPhone 7 上面取消耳机插口的传言早就有了，但是在上周苹果公司的公告证实了这个消息后，它还是成为了一个热门话题。</p><p>对于那些不知道这个最新消息的人再介绍下，苹果公司已经移除了手机上的耳机接口，改为通过闪电接口插入手机。随手机销售的除了闪电接口耳机外，还有一个适配器，如果人们还想在手机上使用现有的耳机，可以使用它。苹果公司也将出售一款新产品：AirPods。它们被戴入你的耳朵后通过无线和手机连接。舍弃耳机接口的最大的好处是能够让手机保持干燥和防水。</p><p>现在苹果公司将在 iPhone 7 上面取消耳机接口已经是一个重大新闻了，我们询问我们的作者，“你怎么看待智能机取消耳机接口？”</p><h3 id="我们的观点" tabindex="-1">我们的观点 <a class="header-anchor" href="#我们的观点" aria-label="Permalink to “我们的观点”">​</a></h3><p>Derrik 认为“苹果公司的这种取消手机耳机接口的行为是为了推进更多昂贵的不遵循公开标准的外围设备。”他也不想每使用五个小时就不得不给 AirPods 充电。尽管他知道 3.5毫米 的耳机接口逐渐过时，作为一个“音质发烧友”，他喜欢新的，开放的标准，但“盈利性企业的推动”让他担心设备的自由性。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/09/headphone-jacks.jpg" alt=""></p><p>Damien 在自从有了蓝牙耳机后的这段日子里基本不怎么使用耳机接口了。总之，他讨厌有线耳机的电线，所以他认为“移除手机耳机接口的做法非常好。”当然他也理解 Derrik 抱怨无线耳机耗尽电源后需要充电会带来不方便，给他一种“没有依靠”的感觉。</p><p>Trevor 直接了当地表明自己认为智能手机移除耳机接口是一种愚蠢的做法，当他了解到 iPhone 7 无法在给手机充电的同时使用耳机后，认为“愚蠢加倍”。他总是使用有线耳机来听音乐或者看视频，从不用蓝牙耳机。因为蓝牙耳机会加速手机电量的消耗，所以他用有线耳机。</p><p>Simon 并不是有线耳机的忠诚用户。他并没有见过太多为了留出更多空间而移除耳机接口的手机产品。他认为“接下来要看顾客是喜欢无线耳机、适配器、防水塞，还是 AirPods，闪电接口或适配器”。他认为不应该这么快就移除智能机的耳机接口，他更喜欢公共的可以适配所有的标准。</p><p>James 认为现在的无线技术已经足够成熟，所以他认为 iPhone 7 移除耳机接口是一个不错的策略，因为这也能够促进苹果公司硬件产品的销量。他碰巧使用过昂贵的有线耳机，所以就个人经历而言“还没有被说服，”他表示自己的 Xperia 智能手机虽然有耳机插口但是防水性也不差。</p><p>Jeffry 指出“几乎全世界所有科技领域的过渡性尝试，都是在无法从这些尝试中受益的人的强烈反对意见中开始的。”他还记得苹果公司因为移除软盘驱动器和不支持 Flash 曾遭到大量的抨击，但现在两者都已经成为行业规范了。他坚信一切都是为了更好的发展而慢慢演变的，智能机移除耳机接口只是“步入未来的一小步”，而苹果公司“足够勇敢来引导未来智能机的一种走向（顺便通过此方式赚点钱）”。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/09/Writers-Opinion-Headphone-Headset.jpg" alt=""></p><p>Vamsi 并不介意耳机接口的移除，只要“有一个更好的解决方案，适用于使用不同类型耳机和其他的设备的用户”。他不认为通过闪电接口使用耳机是一个不错的解决方案，因为这使得几乎所有的其他耳机废弃。至于蓝牙耳机，他只是不想再使用另外一个设备。此外，他不想争论使用无线耳机可以提高手机的防水性能，因为已经存在不少带有耳机接口的设备防水性能也不错。</p><p>Mahesh 更喜欢用带有耳机接口的智能手机，因为他经常在给手机充电的同时听音乐。他认为我们将会在接下来的几个月看到移除耳机接口后给用户带来的诸多不方便之处。</p><p>Derrik 也不赞同“移除开放标准的接口，使用专有连接”。你可能认为可以通过适配器来使耳机连接手机，但是雷电接口可以被随时关闭，苹果公司也能够随时停止这些适配器的销售。他也指出 AirPods 不会取代蓝牙耳机。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/09/Writers-Opinion-Headphone-AirPods.jpg" alt=""></p><p>至于我，我会在两方面来考虑这个事情：新技术和苹果公司产品的其他方面。自从 iPhone 系列第一款出售以来，我一直都在使用 iPhone 系列手机。但从 2012 年我用 iPhone 5 开始，我没有更换过手机，所以我是有些过时的。我会是第一批买 iPhone 7 的人。我讨厌白色的耳机线在我脸旁，所以我也可能会选择 AirPods。我很欣赏手机防水性能变得更好。至于同时充电和收听的问题，新手机续航时间足够长，所以我不认为这是什么大问题。即使我的旧 iPhone 5 手机，续航时间都可以达到 12 到 20 个小时之间。所以我不认为这是一个问题。</p><p>我们的作者已经给了你很多他们对于智能手机移除耳机接口的看法。你怎么看待这件事？你会想念耳机接口吗？你会从此技术更新中获得乐趣吗？你是会尝试使用 iPhone 5 还是使用 AirPods？让我们在评论区了解你的看法。</p><hr>',21)),r("p",null,[e[1]||(e[1]=t("via: ",-1)),o(a,{href:"https://www.maketecheasier.com/should-smartphones-do-away-with-the-headphone-jack/?utm_medium=feed&utm_source=feedpress.me&utm_campaign=Feed%3A+maketecheasier"},{default:s(()=>[...e[0]||(e[0]=[t("https://www.maketecheasier.com/should-smartphones-do-away-with-the-headphone-jack/?utm_medium=feed&utm_source=feedpress.me&utm_campaign=Feed%3A+maketecheasier",-1)])]),_:1})]),r("p",null,[e[6]||(e[6]=t("作者：",-1)),o(a,{href:"https://www.maketecheasier.com/author/lauratucker/"},{default:s(()=>[...e[2]||(e[2]=[t("Laura Tucker",-1)])]),_:1}),e[7]||(e[7]=t(" 译者：",-1)),o(a,{href:"https://github.com/WangYueScream"},{default:s(()=>[...e[3]||(e[3]=[t("WangYueScream",-1)])]),_:1}),e[8]||(e[8]=t()),o(a,{href:"https://github.com/LemonDemo"},{default:s(()=>[...e[4]||(e[4]=[t("LemonDemo",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),o(a,{href:"https://github.com/jasminepeng"},{default:s(()=>[...e[5]||(e[5]=[t("jasminepeng",-1)])]),_:1})]),r("p",null,[e[12]||(e[12]=t("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),o(a,{href:"https://linux.cn/"},{default:s(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const _=p(m,[["render",u]]);export{A as __pageData,_ as default};
